import React, { useState } from "react";
import { Box, Typography, Button, Grid, Chip } from "@mui/material";
import { useNavigate, Link } from "react-router-dom";
import simulations from "./Simulations";
import { ZB_COLORS } from "./theme";

const categoryColors = {
  Finance: "#ffd600", Agriculture: "#4caf50", Healthcare: "#e91e63",
  Energy: "#ff9800", Education: "#2196f3", Logistics: "#9c27b0",
  Business: "#00bcd4",
};

const leaderboard = [
  { name: "Mwansa C.", sim: "Fintech Startup in Africa", score: 98 },
  { name: "Tembo P.", sim: "Entrepreneurship Bootcamp", score: 95 },
  { name: "Phiri G.", sim: "Healthcare Access Innovation", score: 93 },
  { name: "Banda M.", sim: "Smart Agriculture Solutions", score: 91 },
  { name: "Mutale K.", sim: "Renewable Energy for Communities", score: 89 },
];

export default function SimulationsList({ isLoggedIn }) {
  const navigate = useNavigate();
  const [filter, setFilter] = useState("All");
  const [view, setView] = useState("grid");

  const categories = ["All", ...Array.from(new Set(simulations.map(s => s.category)))];
  const filtered = filter === "All" ? simulations : simulations.filter(s => s.category === filter);

  const handleStart = (simId) => {
    if (!isLoggedIn) navigate("/login");
    else navigate("/Simulation/" + simId);
  };

  return (
    <Box sx={{ maxWidth: 1100, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>
        Explore
      </Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>All simulations</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 4 }}>
        {simulations.length} real-world scenarios across African industries. Each includes model answers and AI feedback.
      </Typography>

      <Grid container spacing={3}>
        <Grid item xs={12} md={8}>
          {/* Filters */}
          <Box sx={{ display: "flex", flexWrap: "wrap", gap: 1, mb: 3 }}>
            {categories.map(cat => (
              <Chip key={cat} label={cat} onClick={() => setFilter(cat)} size="small"
                sx={{
                  cursor: "pointer",
                  background: filter === cat ? "rgba(255,214,0,0.15)" : "rgba(255,255,255,0.05)",
                  border: "0.5px solid " + (filter === cat ? ZB_COLORS.gold : ZB_COLORS.border),
                  color: filter === cat ? ZB_COLORS.gold : "rgba(255,255,255,0.65)",
                  fontFamily: "DM Sans",
                }}
              />
            ))}
          </Box>

          {/* Grid */}
          <Grid container spacing={2}>
            {filtered.map(sim => {
              const catColor = categoryColors[sim.category] || ZB_COLORS.gold;
              return (
                <Grid item xs={12} sm={6} key={sim.id}>
                  <Box sx={{
                    background: ZB_COLORS.cardBg,
                    border: "0.5px solid " + ZB_COLORS.border,
                    borderRadius: "12px", p: 2.5,
                    height: "100%", display: "flex", flexDirection: "column",
                    transition: "all 0.2s ease",
                    "&:hover": { background: ZB_COLORS.cardHover, borderColor: "rgba(255,255,255,0.15)", transform: "translateY(-2px)" },
                  }}>
                    <Box sx={{ display: "flex", justifyContent: "space-between", mb: 1.5, flexWrap: "wrap", gap: 1 }}>
                      <Chip label={sim.category} size="small" sx={{ background: catColor + "18", color: catColor, border: "0.5px solid " + catColor + "40", fontFamily: "DM Sans", fontSize: "0.7rem" }} />
                      {sim.partner && (
                        <Chip label={"🤝 " + sim.partner} size="small" sx={{ background: "rgba(255,255,255,0.05)", color: "rgba(255,255,255,0.5)", fontFamily: "DM Sans", fontSize: "0.65rem", border: "0.5px solid " + ZB_COLORS.border }} />
                      )}
                    </Box>
                    <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "0.95rem", mb: 0.75 }}>
                      {sim.title}
                    </Typography>
                    <Typography sx={{ fontSize: "0.82rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", lineHeight: 1.55, flexGrow: 1, mb: 2 }}>
                      {sim.description.slice(0, 90)}…
                    </Typography>
                    <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                      <Box sx={{ display: "flex", gap: 1.5 }}>
                        <Typography sx={{ fontSize: "0.72rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
                          {sim.tasks.length} tasks
                        </Typography>
                        <Typography sx={{ fontSize: "0.72rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
                          {sim.duration}
                        </Typography>
                      </Box>
                      <Button variant="contained" size="small" onClick={() => handleStart(sim.id)} sx={{ fontSize: "0.78rem", px: 2, py: 0.6 }}>
                        Start →
                      </Button>
                    </Box>
                  </Box>
                </Grid>
              );
            })}
          </Grid>
        </Grid>

        {/* Leaderboard sidebar */}
        <Grid item xs={12} md={4}>
          <Box sx={{ background: ZB_COLORS.navyMid, border: "0.5px solid " + ZB_COLORS.border, borderRadius: "12px", p: 3, position: "sticky", top: 80 }}>
            <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", mb: 0.5 }}>
              🏆 Leaderboard
            </Typography>
            <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 2 }}>
              Top performers this month
            </Typography>
            {leaderboard.map((entry, i) => (
              <Box key={i} sx={{
                display: "flex", alignItems: "center", gap: 1.5, mb: 1.5,
                pb: 1.5, borderBottom: i < leaderboard.length - 1 ? "0.5px solid " + ZB_COLORS.border : "none",
              }}>
                <Box sx={{
                  width: 26, height: 26, borderRadius: "50%",
                  background: i === 0 ? "rgba(255,214,0,0.2)" : i === 1 ? "rgba(192,192,192,0.15)" : i === 2 ? "rgba(205,127,50,0.15)" : "rgba(255,255,255,0.05)",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: "0.75rem", fontWeight: 600,
                  color: i === 0 ? ZB_COLORS.gold : i === 1 ? "#C0C0C0" : i === 2 ? "#CD7F32" : ZB_COLORS.textMuted,
                  flexShrink: 0,
                }}>
                  {i + 1}
                </Box>
                <Box sx={{ flexGrow: 1, minWidth: 0 }}>
                  <Typography sx={{ color: "#fff", fontFamily: "DM Sans", fontSize: "0.875rem", fontWeight: 500 }}>{entry.name}</Typography>
                  <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", fontSize: "0.72rem", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{entry.sim}</Typography>
                </Box>
                <Typography sx={{ color: ZB_COLORS.gold, fontFamily: "Sora", fontWeight: 700, fontSize: "0.875rem", flexShrink: 0 }}>
                  {entry.score}
                </Typography>
              </Box>
            ))}
            <Typography sx={{ fontSize: "0.72rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mt: 1, textAlign: "center" }}>
              Complete simulations to appear on the leaderboard
            </Typography>
          </Box>
        </Grid>
      </Grid>
    </Box>
  );
}
